 useEffect(()=>{const c=(document as any).modelContext;if(!c?.registerTool)return;const lifecycle=new AbortController();c.registerTool({name:'open_ticket',description:'Open an existing accessible road ticket. Does not change its status.',inputSchema:{type:'object',properties:{ticketId:{type:'string'}},required:['ticketId'],additionalProperties:false},annotations:{readOnlyHint:true},execute:(input:any)=>{if(typeof input.ticketId!=='string'||!data?.tickets.some(t=>t.id===input.ticketId))throw new Error('Ticket is not accessible');setSelected(input.ticketId);return {opened:input.ticketId}}},{signal:lifecycle.signal});return()=>lifecycle.abort()},[data]);
 const allTickets=data?.tickets||[],tickets=allTickets.filter(t=>!t.archived),archivedTickets=allTickets.filter(t=>t.archived),active=tickets.filter(t=>!['Verified closed','Rejected','Duplicate'].includes(t.status)),urgent=active.filter(t=>t.severity==='Urgent'),reopened=tickets.filter(t=>t.reopened>0),waiting=tickets.filter(t=>t.status==='Awaiting verification'),mine=tickets.filter(t=>t.analyst===data?.viewer.id||t.reportedBy===data?.viewer.id||t.completedBy===data?.viewer.id||t.closedBy===data?.viewer.id),topTicket=[...active].sort((a,b)=>(b.severity==='Urgent'?1:0)-(a.severity==='Urgent'?1:0))[0];
 const filtered=tickets.filter(t=>(filter==='all'||t.status===filter||(filter==='Urgent'&&t.severity==='Urgent')||(filter==='ReopenedEver'&&t.reopened>0))&&(t.id+' '+t.road+' '+t.title).toLowerCase().includes(q.toLowerCase()));
 const gq=globalQuery.trim().toLowerCase();
