function HeroTicket({ticket,onOpen}:{ticket:Ticket|undefined,onOpen:()=>void}){
 if(!ticket)return <section className="feature-card"><div className="image-wrap"><img src="/logo.png" alt="PaveLedger" style={{objectFit:'contain',padding:24,background:'#f4f6f8'}}/><span className="image-label">NO ACTIVE CASES</span></div><div className="feature-content"><p className="eyebrow">ALL CLEAR</p><h2>Nothing needs attention right now.</h2><p>New tickets will appear here as they come in.</p></div></section>;
 return <section className="feature-card"><div className="image-wrap"><iframe title="Top priority case location" src={`https://www.google.com/maps?q=${ticket.lat},${ticket.lng}&z=16&output=embed`} style={{width:'100%',height:'100%',border:0}} loading="lazy"/><span className="image-label">TOP PRIORITY CASE</span></div><div className="feature-content"><p className="eyebrow">{ticket.severity.toUpperCase()} · {ticket.status}</p><h2>{ticket.road}</h2><p>{ticket.title} · reported {new Date(ticket.created).toLocaleDateString()}</p><button className="secondary" onClick={onOpen}>Inspect this case <ArrowUpRight size={16}/></button></div></section>;
}
function EditContractDocuments({contract,data,reload,persona}:{contract:any,data:any,reload:()=>void,persona:string}){
 const [uploading,setUploading]=useState(false),[err,setErr]=useState('');
 const suffix=persona==='owner'?'':'?persona='+encodeURIComponent(persona);
 async function openDoc(id:string){try{const r=await authorizedFetch('/api/contract-document?contract='+encodeURIComponent(contract.id)+'&id='+encodeURIComponent(id)+(persona==='owner'?'':'&persona='+encodeURIComponent(persona)));const d=await r.json();if(!r.ok)throw new Error(d.error);window.open(d.url,'_blank','noopener,noreferrer')}catch(e){setErr((e as Error).message)}}
 return <div className="evidence-panel"><h3>Contract documents</h3>{!(contract.documents||[]).length&&<p className="muted">No documents uploaded.</p>}{(contract.documents||[]).map((d:any)=><div className="evidence-row" key={d.id}><button className="text-button" onClick={()=>openDoc(d.id)}>{d.name}</button><small>{(d.bytes/1024).toFixed(0)} KB</small></div>)}<form className="form" onSubmit={async e=>{e.preventDefault();const form=e.currentTarget;setErr('');setUploading(true);try{const body=new FormData(form);body.set('contract',contract.id);body.set('revision',String(data.revision));const r=await authorizedFetch('/api/contract-document'+suffix,{method:'POST',body});const d=await r.json();if(!r.ok)throw new Error(d.error);form.reset();await reload()}catch(e){setErr((e as Error).message)}finally{setUploading(false)}}}><label>Upload document (contract PDF, addendum, etc.)<input type="file" name="file" required/></label><button className="secondary" disabled={uploading}>{uploading?'Uploading…':'Upload document'}</button></form>{err&&<p role="alert" className="access-error">{err}</p>}</div>;
}
function AddToTeamPicker({team,data,mutate,busy}:{team:string,data:any,mutate:(b:any)=>Promise<boolean>,busy:boolean}){
 const [pick,setPick]=useState('none');
 const eligible=data.members.filter((m:Member)=>!(m.teams||[]).includes(team)&&(m.teams||[]).length<3&&['Team lead','Analyst','Reviewer','Head Analyst'].includes(m.role));
 return <div className="two-cols"><Pick label="Member" value={pick} onChange={setPick} items={[{value:'none',label:'Choose a member'},...eligible.map((m:Member)=>({value:m.id,label:m.name+' · '+m.role}))]}/><button className="primary" disabled={busy||pick==='none'} onClick={async()=>{const m=data.members.find((x:Member)=>x.id===pick);if(!m)return;if(await mutate({action:'memberUpdate',memberId:m.id,name:m.name,email:m.email,role:m.role,teams:[...(m.teams||[]),team].slice(0,3),contractor:m.contractor||'',vehicleTag:m.vehicleTag||'',authUserId:m.authUserId,active:m.active!==false}))setPick('none')}}>Add to team</button></div>;
}
function TicketTable({tickets,onSelect,onPriority,canEditPriority,busy,viewer,onStageChange}:{tickets:Ticket[],onSelect:(id:string)=>void,onPriority:(id:string,severity:string)=>void,canEditPriority:boolean,busy:boolean,viewer:Member,onStageChange:(t:Ticket,stage:string)=>void}){const stageOptions=(t:Ticket)=>nextStages(t).filter(s=>permitted(viewer,t,s));return <Table><TableHeader><TableRow><TableHead>Ticket</TableHead><TableHead>Priority</TableHead><TableHead>Stage</TableHead><TableHead>Assigned team</TableHead><TableHead>Contractor</TableHead><TableHead>Observations</TableHead><TableHead/></TableRow></TableHeader><TableBody>{tickets.map(t=><TableRow key={t.id}><TableCell><button className="table-title" onClick={()=>onSelect(t.id)}><strong>{t.road}</strong><small>{t.id}</small><small className="block muted">Updated {new Date(t.updated).toLocaleString()}</small></button></TableCell><TableCell>{canEditPriority?<select value={t.severity} disabled={busy} onChange={e=>onPriority(t.id,e.target.value)} className={t.severity==='Urgent'?'priority-urgent':'muted'}><option>Urgent</option><option>Standard</option><option>Low</option></select>:<span className={t.severity==='Urgent'?'priority-urgent':'muted'}>{t.severity}</span>}</TableCell><TableCell><Badge status={t.status}/>{t.reopened>0&&<small className="block muted">Reopened ×{t.reopened}</small>}</TableCell>{stageOptions(t).length>0&&<select value="" disabled={busy} onChange={e=>{const v=e.target.value;if(v)onStageChange(t,v)}} style={{display:'block',marginTop:4,fontSize:12,width:'100%'}}><option value="">Change stage...</option>{stageOptions(t).map(s=><option key={s} value={s}>{s}</option>)}</select>}<TableCell>{t.team}</TableCell><TableCell>{t.contractor||'No contractor'}</TableCell><TableCell>{t.observations}</TableCell><TableCell><button aria-label={'Open '+t.id} className="icon-btn" onClick={()=>onSelect(t.id)}><ArrowUpRight size={18}/></button></TableCell></TableRow>)}</TableBody></Table>}
function Detail({ticket:t,data,mutate,busy,reload,persona}:{ticket:Ticket,data:Data,mutate:(v:any)=>Promise<boolean>,busy:boolean,reload:()=>Promise<void>,persona:string}){
const [note,setNote]=useState(''),[next,setNext]=useState('none'),[team,setTeam]=useState(t.team),[analyst,setAnalyst]=useState(t.analyst||'none'),[contract,setContract]=useState('none'),[confirmed,setConfirmed]=useState(false),[verified,setVerified]=useState(false),[evidenceId,setEvidenceId]=useState('none'),[duplicateOf,setDuplicateOf]=useState('none'),[shared,setShared]=useState(false);
const [contractorPick,setContractorPick]=useState('none');
const available=nextStages(t).filter(s=>permitted(data.viewer,t,s));
function notice(){const c=data.contracts.find(x=>x.id===t.contractId);download(t.id+'_Notice_DRAFT.txt',`DRAFT - NOT SENT\nPaveLedger repair review request\n\nTo: ${c?.poc||'POC to verify'} (${c?.email||'email to verify'})\nTicket: ${t.id}\nRoad: ${t.road}\nCoordinates: ${t.lat}, ${t.lng}; estimated accuracy +/- ${t.accuracy} m\nIssue: ${t.title}\nContract: ${c?.id||'Contract requires verification'}\nScope: ${c?.scope||'Scope requires verification'}\nObserved: ${t.created}\nEvidence: ${(t.evidence||[]).length} uploaded file(s). Download and attach the approved redacted image and secure case link before authorized sending. The displayed sample image is not evidence.\n\nPlease review the reported defect and confirm responsibility, intended repair action and schedule under the applicable contract. This request does not determine liability. Urgent municipal safety action continues independently.\n\nVerify all record values against the evidence. No message was sent.`)}
return <div className="detail-body"><div className="detail-summary"><Badge status={t.status}/>{data.viewer.role!=='Auditor'?<select value={t.severity} disabled={busy} onChange={e=>mutate({action:'priority',id:t.id,severity:e.target.value})} className={t.severity==='Urgent'?'priority-urgent':'muted'}><option>Urgent</option><option>Standard</option><option>Low</option></select>:<span className={t.severity==='Urgent'?'priority-urgent':'muted'}>{t.severity} priority</span>}{t.reopened>0&&<span className="muted">· Reopened ×{t.reopened}</span>}</div><Tabs defaultValue="investigate"><TabsList><TabsTrigger value="investigate">Ticket</TabsTrigger><TabsTrigger value="history">Activity</TabsTrigger><TabsTrigger value="assignment">Assignment</TabsTrigger></TabsList><TabsContent value="investigate"><div className="evidence"><iframe title="Ticket location" src={`https://www.google.com/maps?q=${t.lat},${t.lng}&z=16&output=embed`} style={{width:'100%',height:280,border:0}} loading="lazy"/><span>Map centered on the reported location — photos are below under Uploaded case evidence</span></div><h3>{t.title}</h3><div className="facts"><div><MapPin size={17}/><span><b>{t.lat.toFixed(5)}, {t.lng.toFixed(5)}</b><small>Estimated GPS accuracy ±{t.accuracy} m · demo coordinates</small></span></div><div><Camera size={17}/><span><b>{t.source}</b><small>{t.confidence?Math.round(t.confidence*100)+'% illustrative model score':'Manual report'} · {t.observations} observations</small></span></div></div><p className="footnote">Depth and area are unmeasured. A model score is not a calibrated probability or a warranty decision.</p><div className="warranty-box"><ShieldCheck size={20}/><div><strong>{t.warranty}</strong><p>{t.contractor||'No contractor established'}</p></div></div>{['Admin','Team lead'].includes(data.viewer.role)&&<div className="form"><h3>Contractor &amp; warranty</h3><Pick label="Assign contractor" value={contractorPick} onChange={setContractorPick} items={[{value:'none',label:'Choose a contract covering this road'},...data.contracts.filter(c=>c.road===t.road).map(c=>({value:c.id,label:c.id+' · '+c.contractor}))]}/><button className="secondary" disabled={busy||contractorPick==='none'} onClick={()=>mutate({action:'assignContractor',id:t.id,contractId:contractorPick})}>Assign contractor</button>{!data.contracts.some(c=>c.road===t.road)&&<p className="footnote">No contracts registered for "{t.road}" yet. Register one under Contracts, using the exact same road name, then it will appear here.</p>}</div>}<p className="footnote">{t.note}</p>{data.viewer.role!=='Auditor'&&<div className="form"><h3>Record the next step</h3>{data.viewer.role!=='Contractor'&&<label className="check"><Checkbox checked={shared} onCheckedChange={v=>setShared(v===true)}/>Share this note with the assigned contractor</label>}<label>Ticket note<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Evidence reviewed, decision, and next action…"/></label><Pick label="Next stage" value={next} onChange={v=>{setNext(v);setConfirmed(false);setVerified(false)}} items={[{value:'none',label:'Choose next stage'},...available.map(s=>({value:s,label:s}))]}/>{next==='Notice prepared'&&<><Pick label="Contract" value={contract} onChange={setContract} items={[{value:'none',label:'Select the signed contract'},...data.contracts.map(c=>({value:c.id,label:c.id+' · '+c.road}))]}/><label className="check"><Checkbox checked={confirmed} onCheckedChange={v=>setConfirmed(v===true)}/>I reviewed the location, work scope, dates, and notice requirements.</label></>}{next==='Duplicate'&&<Pick label="Primary case" value={duplicateOf} onChange={setDuplicateOf} items={[{value:'none',label:'Select primary ticket'},...data.tickets.filter(x=>x.id!==t.id&&!['Duplicate','Rejected'].includes(x.status)).map(x=>({value:x.id,label:x.id+' · '+x.road}))]}/>} {next==='Verified closed'&&<><Pick label="Verification evidence" value={evidenceId} onChange={setEvidenceId} items={[{value:'none',label:'Select eligible repeat photograph'},...(t.evidence||[]).filter(e=>eligibleVerification(t,e)).map(e=>({value:e.id,label:e.name+' · '+e.capturedAt}))]}/><label className="check"><Checkbox checked={verified} onCheckedChange={v=>setVerified(v===true)}/>I independently reviewed the selected clear repeat image; it shows the same location and lane repaired.</label></>}<div className="button-row"><button disabled={busy||next==='none'} className="primary" onClick={async()=>{if(await mutate({action:'transition',id:t.id,status:next,note,contract,scopeConfirmed:confirmed,verification:verified?'clear-pass':'',evidenceId,duplicateOf,visibility:shared?'shared':'internal'})){setNext('none');setNote('')}}}>Update stage</button>{['Admin','Team lead','Analyst','Head Analyst','Reviewer'].includes(data.viewer.role)&&<button disabled={busy} className="secondary" onClick={async()=>{if(await mutate({action:'note',id:t.id,note,visibility:shared?'shared':'internal'}))setNote('')}}>Add note</button>}</div></div>}<EvidencePanel ticket={t} data={data} reload={reload} persona={persona}/>{t.duplicateOf&&<p className="footnote">Primary case: {t.duplicateOf}</p>}<button className="text-button notice" onClick={notice}><FileText size={17}/>Download draft contractor notice</button><p className="footnote">Draft download only. Email delivery is not connected.</p><div className="button-row">{t.archived?<><span className="muted">Archived</span>{['Admin','Team lead','Director'].includes(data.viewer.role)&&<button className="secondary" disabled={busy} onClick={()=>mutate({action:'unarchive',id:t.id})}>Unarchive</button>}</>:<>{['Admin','Team lead','Director'].includes(data.viewer.role)&&<button className="secondary" disabled={busy} onClick={()=>mutate({action:'archive',id:t.id})}>Archive case</button>}{['Analyst','Head Analyst'].includes(data.viewer.role)&&(t.archiveRequested?<span className="muted">Archive requested</span>:<button className="secondary" disabled={busy} onClick={()=>mutate({action:'requestArchive',id:t.id})}>Request archive</button>)}</>}</div></TabsContent><TabsContent value="history"><div className="timeline">{[...t.history].reverse().map((h,i)=><div key={i}><span style={{background:colors[h.action]||'#79869a'}}/><small>{new Date(h.at).toLocaleString()}</small><h3>{h.action}</h3><p>{h.note}</p><small>{h.actor}</small></div>)}</div>{t.verification&&<p className="warranty-box">{t.verification}</p>}</TabsContent><TabsContent value="assignment"><div className="form"><h3>Route the ticket</h3><p className="muted">Assign a team and then an analyst. Saving an analyst assignment creates an in-app notification.</p><Pick label="Team" value={team} onChange={v=>{setTeam(v);setAnalyst('none')}} items={data.teams.map(x=>({value:x,label:x}))}/><Pick label="Analyst" value={analyst} onChange={setAnalyst} items={[{value:'none',label:'Team queue · unassigned'},...data.members.filter(m=>m.role==='Analyst'&&(m.teams||[]).includes(team)&&isActive(m)).map(m=>({value:m.id,label:m.name}))]}/><button disabled={busy||!['Admin','Team lead'].includes(data.viewer.role)} className="primary" onClick={()=>mutate({action:'assign',id:t.id,team,analyst:analyst==='none'?'':analyst,note:'Assignment updated by '+data.viewer.name})}>Save assignment</button>{['Head Analyst','Team lead'].includes(data.viewer.role)&&<button disabled={busy} className="secondary" onClick={()=>mutate({action:'escalate',id:t.id})}>Escalate to {data.viewer.role==='Head Analyst'?'Team lead':'Director'}</button>}{t.escalatedTo&&<p className="muted">Currently escalated to {t.escalatedTo}.</p>}</div></TabsContent></Tabs></div>
}
function MemberForm({data,onSave,busy,initial}:{data:Data,onSave:(v:any)=>void,busy:boolean,initial?:Member}){const [role,setRole]=useState<string>(initial?.customRole||initial?.role||'Analyst'),[teams,setTeams]=useState<string[]>(initial?.teams||[]),[firm,setFirm]=useState(initial?.contractor||'none'),[active,setActive]=useState(initial?.active!==false),base=(data.customRoles||[]).find(r=>r.name===role)?.base||role;return <form className="form" onSubmit={e=>{e.preventDefault();onSave({...Object.fromEntries(new FormData(e.currentTarget)),role,teams,contractor:firm==='none'?'':firm,active})}}><label>Name<input required name="name" defaultValue={initial?.name}/></label><label>Sign-in email<input required type="email" name="email" defaultValue={initial?.email}/></label><label>Phone number<input name="phone" type="tel" defaultValue={initial?.phone||''} placeholder="e.g. +1 555 123 4567"/></label><label>Supabase authentication user ID<input name="authUserId" required defaultValue={initial?.authUserId||''} placeholder="Copy the user's UUID from Authentication → Users"/></label><Pick label="Role" value={role} onChange={v=>setRole(v)} items={[...roles.map(x=>({value:x as string,label:x as string})),...(data.customRoles||[]).map(x=>({value:x.name,label:x.name+' (custom)'}))]}/><div className="form"><p className="footnote">Teams (choose up to 3)</p>{data.teams.map(t=><label className="check" key={t}><Checkbox checked={teams.includes(t)} disabled={!teams.includes(t)&&teams.length>=3} onCheckedChange={v=>setTeams(v?[...teams,t].slice(0,3):teams.filter(x=>x!==t))}/>{t}</label>)}</div>{base==='Contractor'&&<Pick label="Firm" value={firm} onChange={setFirm} items={[{value:'none',label:'Choose contractor firm'},...Array.from(new Set(data.contracts.map(c=>c.contractor))).map(x=>({value:x,label:x}))]}/>}{role==='Vehicle'&&<label>Vehicle tag<input name="vehicleTag" required defaultValue={initial?.vehicleTag||''} placeholder="e.g. Truck-07"/></label>}<label className="check"><Checkbox checked={active} onCheckedChange={v=>setActive(v===true)}/>Active membership</label><button className="primary" disabled={busy}>{initial?'Save access':'Add user'}</button></form>}
function CustomRolesPanel({data,isAdmin,busy,mutate}:{data:Data,isAdmin:boolean,busy:boolean,mutate:(b:any)=>Promise<boolean>}){
const BASES=['Team lead','Analyst','Head Analyst','Reviewer','Contractor','Auditor','Director'];
const VIS:Record<string,string>={base:'Same as base role',own:'Own tickets only',team:"Own teams' tickets",all:'All tickets'};
const [draft,setDraft]=useState<null|{previous:string,name:string,base:string,visibility:string,caps:string[]}>(null);
const list=data.customRoles||[];
const usedBy=(n:string)=>data.members.filter(m=>m.customRole===n).length;
return <div style={{marginTop:28}}>
<div className="section-head"><div><h2>Custom roles</h2><p>Create your own roles. Each one is based on a built-in role, which sets the workflow rules, and has its own visibility and allowed actions.</p></div>{isAdmin&&!draft&&<button className="primary" onClick={()=>setDraft({previous:'',name:'',base:'Analyst',visibility:'base',caps:['comment']})}>Add role</button>}</div>
{!list.length&&!draft&&<p className="muted">No custom roles yet.</p>}
{!!list.length&&<Table><TableHeader><TableRow><TableHead>Role</TableHead><TableHead>Based on</TableHead><TableHead>Visibility</TableHead><TableHead>Allowed actions</TableHead><TableHead>Users</TableHead><TableHead/></TableRow></TableHeader><TableBody>{list.map(r=><TableRow key={r.name}><TableCell><strong>{r.name}</strong></TableCell><TableCell>{r.base}</TableCell><TableCell>{VIS[r.visibility]||r.visibility}</TableCell><TableCell>{CAPABILITIES.filter(c=>r.caps.includes(c.key)).map(c=>c.label).join(', ')||'None'}</TableCell><TableCell>{usedBy(r.name)}</TableCell><TableCell>{isAdmin&&<div className="button-row"><button className="secondary" disabled={busy} onClick={()=>setDraft({previous:r.name,name:r.name,base:r.base,visibility:r.visibility,caps:[...r.caps]})}>Edit</button><button className="secondary" disabled={busy} onClick={()=>{if(confirm('Delete custom role "'+r.name+'"?'))mutate({action:'customRoleDelete',name:r.name})}}>Delete</button></div>}</TableCell></TableRow>)}</TableBody></Table>}
{draft&&<form className="form" onSubmit={async e=>{e.preventDefault();if(await mutate({action:'customRoleSave',name:draft.name,previous:draft.previous||undefined,base:draft.base,visibility:draft.visibility,caps:draft.caps}))setDraft(null)}}>
<label>Role name<input required minLength={2} maxLength={40} value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="e.g. Field inspector"/></label>
<p className="footnote">Based on (sets which stages this role can move tickets between)</p>
<Pick label="Based on" value={draft.base} onChange={v=>setDraft({...draft,base:v})} items={BASES.map(x=>({value:x,label:x}))}/>
<p className="footnote">Which tickets this role can see (does not apply when based on Contractor)</p>
<Pick label="Visibility" value={draft.visibility} onChange={v=>setDraft({...draft,visibility:v})} items={Object.entries(VIS).map(([value,label])=>({value,label}))}/>
<div className="form"><p className="footnote">Allowed actions</p>{CAPABILITIES.map(c=><label className="check" key={c.key}><Checkbox checked={draft.caps.includes(c.key)} onCheckedChange={v=>setDraft({...draft,caps:v?[...draft.caps,c.key]:draft.caps.filter(x=>x!==c.key)})}/>{c.label}</label>)}</div>
<div className="button-row"><button className="primary" disabled={busy}>Save role</button><button type="button" className="secondary" onClick={()=>setDraft(null)}>Cancel</button></div>
</form>}
<p className="footnote">A role cannot be deleted, or have its base role changed, while users are assigned to it. Administrator-only safeguards still apply to every role.</p>
</div>}
function EvidencePanel({ticket:t,data,reload,persona}:{ticket:Ticket,data:Data,reload:()=>Promise<void>,persona:string}){
const [uploading,setUploading]=useState(false),[error,setError]=useState('');const suffix=persona==='owner'?'':'?persona='+encodeURIComponent(persona);
const [thumbs,setThumbs]=useState<Record<string,string>>({});
useEffect(()=>{let active=true;authorizedFetch('/api/evidence-urls?ticket='+encodeURIComponent(t.id)+(persona==='owner'?'':'&persona='+encodeURIComponent(persona))).then(r=>r.json()).then(d=>{if(active&&d.urls)setThumbs(d.urls)}).catch(()=>{});return()=>{active=false}},[t.id,(t.evidence||[]).length,persona]);
async function openFile(id:string){try{const r=await authorizedFetch('/api/evidence?ticket='+encodeURIComponent(t.id)+'&id='+encodeURIComponent(id)+(persona==='owner'?'':'&persona='+encodeURIComponent(persona)));const d=await r.json();if(!r.ok)throw new Error(d.error);window.open(d.url,'_blank','noopener,noreferrer')}catch(e){setError((e as Error).message)}}
return <section className="evidence-panel"><h3>Uploaded case evidence</h3>{!(t.evidence||[]).length&&<p className="muted">No uploaded photographs. The sample image above is illustrative.</p>}{(t.evidence||[]).map(e=><div className="evidence-row" key={e.id} style={{display:'flex',alignItems:'center',gap:12}}><button onClick={()=>openFile(e.id)} title="Open full image" style={{padding:0,border:'1px solid #e5e7eb',borderRadius:6,cursor:'pointer',background:'none',flexShrink:0}}>{thumbs[e.id]?<img src={thumbs[e.id]} alt={e.name} style={{width:64,height:64,objectFit:'cover',borderRadius:5,display:'block'}}/>:<div style={{width:64,height:64,borderRadius:5,background:'#f0f1f3'}}/>}</button><div><button className="text-button" onClick={()=>openFile(e.id)}>{e.name}</button><small className="block muted">{e.purpose} · {e.quality} · {e.lane} · ±{e.accuracy} m</small><small className="block muted">{new Date(e.capturedAt).toLocaleString()}</small></div></div>)}{data.viewer.role!=='Auditor'&&!['Verified closed','Rejected','Duplicate'].includes(t.status)&&<form className="form" onSubmit={async ev=>{ev.preventDefault();const form=ev.currentTarget;setError('');setUploading(true);try{const body=new FormData(form);body.set('ticket',t.id);body.set('revision',String(data.revision));body.set('authorized',body.has('authorized')?'true':'false');body.set('capturedAt',new Date(String(body.get('capturedAt'))).toISOString());const r=await authorizedFetch('/api/evidence'+suffix,{method:'POST',body});const d=await r.json();if(!r.ok)throw new Error(d.error);form.reset();await reload();toast.success('Evidence stored')}catch(e){setError((e as Error).message)}finally{setUploading(false)}}}><label>Photograph up to 3 MB<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" name="file" required/></label><label>Purpose<select name="purpose" defaultValue={data.viewer.role==='Contractor'?'repair':'detection'}>{(data.viewer.role==='Contractor'?['repair']:['detection','repair','verification']).map(x=><option key={x}>{x}</option>)}</select></label><label>Actual capture date and time<input type="datetime-local" name="capturedAt" step="1" required/></label><div className="two-cols"><label>Latitude<input type="number" name="lat" step="any" required defaultValue={t.lat}/></label><label>Longitude<input type="number" name="lng" step="any" required defaultValue={t.lng}/></label><label>Accuracy in metres<input type="number" name="accuracy" min="0.1" step="0.1" required defaultValue={t.accuracy}/></label><label>Lane<input name="lane" required defaultValue={t.lane}/></label></div><label>Visibility<select name="quality"><option value="clear">Clear view of defect location</option><option value="unclear">Obscured or uncertain</option></select></label>{data.viewer.role!=='Contractor'&&<label className="check"><input type="checkbox" name="shared"/>Share this redacted image with the assigned contractor</label>}<label className="check"><input type="checkbox" name="authorized" required/>I am authorized to upload this image and have removed unnecessary personal information.</label><p className="footnote">Capture metadata is entered manually in this pilot. It is not authenticated GPS or a vehicle capture attestation.</p><button className="secondary" disabled={uploading}>{uploading?'Uploading…':'Upload evidence'}</button></form>}{error&&<p role="alert" className="access-error">{error}</p>}</section>}
